// Generate k-th permutation of size len in lexicographic order from given numbers
function kthPerm(nums, k) {
    // nums sorted ascending
    let len = nums.length;
    let res = [];
    k = k - 1n; // 0-based
    for (let i = 0; i < len; i++) {
        let f = fact[len - 1 - i];
        let idx = k / f;
        if (idx >= BigInt(nums.length)) idx = BigInt(nums.length - 1);
        k = k % f;
        let pos = Number(idx);
        res.push(nums[pos]);
        nums.splice(pos, 1);
    }
    return res;
}

