const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(BigInt);
if (input.length === 0) process.exit(0);
let n = Number(input[0]);
let k = input[1];

// Precompute factorials up to 50, capped at 1e18
const MAXN = 50;
const LIMIT = BigInt(1e18);
let fact = Array(MAXN + 1).fill(0n);
fact[0] = 1n;
for (let i = 1; i <= MAXN; i++) {
    fact[i] = fact[i - 1] * BigInt(i);
    if (fact[i] > LIMIT) fact[i] = LIMIT;
}

let used = Array(n + 1).fill(false);
let perm = Array(n + 1).fill(0);

function solve(pos, k) {
    if (pos > n) return;
    // if remaining length <= 20, we can brute-force permutations
    if (n - pos + 1 <= 20) {
        let remaining = [];
        for (let i = 1; i <= n; i++) if (!used[i]) remaining.push(i);
        remaining.sort((a, b) => a - b);
        let len = remaining.length;

        // generate k-th permutation (1-based) of remaining
        k = k - 1n;
        for (let i = 0; i < len; i++) {
            let f = fact[len - 1 - i];
            let idx = k / f;
            k = k % f;
            let val = remaining[Number(idx)];
            perm[pos + i] = val;
            used[val] = true;
            remaining.splice(Number(idx), 1);
        }
        return;
    }

    // Option 1: fixed point at pos
    let cntFixed = fact[n - pos];
    if (cntFixed > LIMIT) cntFixed = LIMIT;
    if (k <= cntFixed) {
        // choose smallest unused value for fixed point
        for (let v = 1; v <= n; v++) {
            if (!used[v]) {
                perm[pos] = v;
                used[v] = true;
                break;
            }
        }
        solve(pos + 1, k);
        return;
    }
    k -= cntFixed;

    // Option 2: 2-cycle starting at pos
    // choose second element > first element
    // first element is smallest unused
    let first = -1;
    for (let v = 1; v <= n; v++) {
        if (!used[v]) {
            first = v;
            break;
        }
    }
    used[first] = true;
    // count how many choices for second
    let candidates = [];
    for (let v = first + 1; v <= n; v++) if (!used[v]) candidates.push(v);

    for (let idx = 0; idx < candidates.length; idx++) {
        let second = candidates[idx];
        let cnt = fact[n - pos - 1];
        if (cnt > LIMIT) cnt = LIMIT;
        if (k <= cnt) {
            perm[pos] = first;
            perm[pos + 1] = second;
            used[second] = true;
            solve(pos + 2, k);
            return;
        }
        k -= cnt;
    }
}

